mapper.insert:
SELECT NVL(MAX(CHAT_SEND_NO),0)+1 FROM CHAT_SEND
INSERT INTO CHAT_SEND(CHAT_SEND_NO, CHAT_ROOM_NO, SENDER_NO, CHAT_SEND_CONTENT
,FILE_GROUP_NO
, CHAT_SEND_DATE, CHAT_SEND_DEL, RECEIVER_NO) VALUES(#{chatSendNo},#{chatRoomNo},#{senderNo},#{chatSendContent}
,#{fileGroupNo}
,sysdate,1,#{receiverNo})

mapper.select:
select * from file_detail fd, file_group fg
where fg.file_group_no=fd.file_group_no
and fd.file_group_no=#{fileGroupNo}
